  `purpose` enum('invite','reset','email_change','account_delete') NOT NULL,
  `payload` varchar(255) DEFAULT NULL,
  `expires_at` datetime NOT NULL,
  `used_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `UK_user_token_token` (`token`),
  KEY `FK_user_token_user` (`user_id`),
  CONSTRAINT `FK_user_token_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `watch_link` (
  `user_id` bigint(20) unsigned NOT NULL,
  `token_hash` char(64) DEFAULT NULL,
  `token_enc` text DEFAULT NULL,
  `route_id` bigint(20) unsigned DEFAULT NULL,
  `unit` varchar(10) NOT NULL DEFAULT 'metric',
  `colors` text DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`user_id`),
  UNIQUE KEY `UQ_watch_link_token` (`token_hash`),
  KEY `IDX_watch_link_route` (`route_id`),
  CONSTRAINT `FK_watch_link_route` FOREIGN KEY (`route_id`) REFERENCES `route` (`id`) ON DELETE SET NULL,
  CONSTRAINT `FK_watch_link_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `weather_forecast` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `lat` decimal(6,2) NOT NULL,
  `lng` decimal(6,2) NOT NULL,
  `region_code` varchar(20) NOT NULL,
  `source` varchar(50) NOT NULL,
  `model` varchar(100) DEFAULT NULL,
  `generated_at` datetime DEFAULT NULL,
  `fetched_at` datetime NOT NULL,
  `payload` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`payload`)),
  PRIMARY KEY (`id`),
  UNIQUE KEY `UK_weather_forecast_coords` (`lat`,`lng`),
  KEY `IX_weather_forecast_fetched_at` (`fetched_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `windshelter` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `poi_id` bigint(20) unsigned NOT NULL,
  `direction` char(16) NOT NULL DEFAULT '0000000000000000',
  PRIMARY KEY (`id`),
  UNIQUE KEY `UK_poi_id` (`poi_id`),
  CONSTRAINT `FK_windshelter_poi` FOREIGN KEY (`poi_id`) REFERENCES `poi` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

